data GlobalCmds = GlobalCmds
  { pCreateInstance :: FunPtr C_createInstance
  , pEnumerateInstanceExtensionProperties :: FunPtr C_enumerateInstanceExtensionProperties
  , pEnumerateInstanceLayerProperties :: FunPtr C_enumerateInstanceLayerProperties
  , pEnumerateInstanceVersion :: FunPtr C_enumerateInstanceVersion
  }

-- | Resolve every GlobalCmds entry point (canonical spelling first,
-- then alias spellings for drivers predating promotion).
initGlobalCmds :: () -> IO GlobalCmds
initGlobalCmds h =
  GlobalCmds
    <$> (castCommandPtr <$> getFirstProcAddr (nullPtr :: Ptr ()) ["vkCreateInstance"])
    <*> (castCommandPtr <$> getFirstProcAddr (nullPtr :: Ptr ()) ["vkEnumerateInstanceExtensionProperties"])
    <*> (castCommandPtr <$> getFirstProcAddr (nullPtr :: Ptr ()) ["vkEnumerateInstanceLayerProperties"])
    <*> (castCommandPtr <$> getFirstProcAddr (nullPtr :: Ptr ()) ["vkEnumerateInstanceVersion"])

-- | The global commands, resolved once (the loader always exposes
-- them; no other global state exists in lithon).
globalCmds :: GlobalCmds
globalCmds = unsafePerformIO (initGlobalCmds ())
{-# NOINLINE globalCmds #-}

