-- | Resolve every InstanceCmds entry point (canonical spelling first,
-- then alias spellings for drivers predating promotion).
initInstanceCmds :: Ptr () -> IO InstanceCmds
initInstanceCmds h =
  InstanceCmds
    <$> (castCommandPtr <$> getFirstProcAddr h ["vkAcquireXlibDisplayEXT"])
    <*> (castCommandPtr <$> getFirstProcAddr h ["vkCreateDebugUtilsMessengerEXT"])
    <*> (castCommandPtr <$> getFirstProcAddr h ["vkCreateDevice"])
    <*> (castCommandPtr <$> getFirstProcAddr h ["vkCreateDisplayModeKHR"])
