    <*> (castCommandPtr <$> getFirstProcAddr h ["vkCreateWin32SurfaceKHR"])
    <*> (castCommandPtr <$> getFirstProcAddr h ["vkCreateXcbSurfaceKHR"])
    <*> (castCommandPtr <$> getFirstProcAddr h ["vkCreateXlibSurfaceKHR"])
    <*> (castCommandPtr <$> getFirstProcAddr h ["vkDestroyDebugUtilsMessengerEXT"])
    <*> (castCommandPtr <$> getFirstProcAddr h ["vkDestroyInstance"])
    <*> (castCommandPtr <$> getFirstProcAddr h ["vkDestroySurfaceKHR"])
    <*> (castCommandPtr <$> getFirstProcAddr h ["vkEnumerateDeviceExtensionProperties"])
    <*> (castCommandPtr <$> getFirstProcAddr h ["vkEnumeratePhysicalDeviceGroups"])
    <*> ( castCommandPtr
